    public void testRandom_default() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(8);
        Assert.assertTrue(result.length() == 8);
        Assert.assertTrue(result.matches("[a-zA-Z0-9]*"));
    }

    @Test
    public void testRandom_letters() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(5, true, false);
        Assert.assertTrue(result.length() == 5);
        Assert.assertTrue(result.matches("[a-zA-Z]*"));
    }

    @Test
    public void testRandom_numbers() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(5, false, true);
        Assert.assertTrue(result.length() == 5);
        Assert.assertTrue(result.matches("[0-9]*"));
    }

    @Test
    public void testRandom_lettersAndNumbers() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(5, true, true);
        Assert.assertTrue(result.length() == 5);
        Assert.assertTrue(result.matches("[a-zA-Z0-9]*"));
    }

    @Test
    public void testRandom_startEnd() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(3, 1, 9);
        Assert.assertTrue(result.length() == 3);
        Assert.assertTrue(result.matches("[1-9]*"));
    }

    @Test
    public void testRandom_countZero() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(0);
        Assert.assertTrue(result.length() == 0);
    }

