            org.apache.commons.lang3.RandomStringUtils.random(3, 1, 10);
            Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            Assert.assertTrue(e.getMessage().contains("start"));
            Assert.assertTrue(e.getMessage().contains("end"));
        }
    }

    @Test
    public void testRandom_nullChars() {
        String result = org.apache.commons.lang3.RandomStringUtils.random(5, false, false, null);
        Assert.assertTrue(result.length() == 5);
        Assert.assertTrue(result.matches("[a-z0-9]*"));
    }
}
